-- Warband suppliers: merchants, menus and prices. Generated by tools/warband-suppliers.py
-- Apply on a world with no supplier rows in place; revert.sql is the exact inverse.
START TRANSACTION;

-- module tables
CREATE TABLE IF NOT EXISTS `warband_setting` (
  `setting` VARCHAR(48) NOT NULL,
  `value` DOUBLE NOT NULL DEFAULT 0,
  PRIMARY KEY (`setting`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `warband_supplier_price` (
  `entry` INT UNSIGNED NOT NULL,
  `quality` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `base_buy` INT UNSIGNED NOT NULL DEFAULT 0,
  `base_sell` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`entry`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- this file owns these rows; clear them so a second application is harmless
DELETE FROM `gossip_menu_option` WHERE `MenuID` BETWEEN 90100 AND 90182;
DELETE FROM `gossip_menu` WHERE `MenuID` BETWEEN 90100 AND 90182;
DELETE FROM `npc_text` WHERE `ID` BETWEEN 90050 AND 90132;
DELETE FROM `npc_vendor` WHERE `entry` BETWEEN 910000 AND 910433;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 910000 AND 910433;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 910000 AND 910433;

